use std::sync::atomic::{AtomicBool, Ordering};

pub static NEW_CHECKOUT: AtomicBool = AtomicBool::new(false);

pub fn load_flags(cfg: &Config) {
    NEW_CHECKOUT.store(cfg.new_checkout, Ordering::Relaxed);
}

pub fn checkout(cart: &Cart) -> Receipt {
    if NEW_CHECKOUT.load(Ordering::Relaxed) { new_checkout(cart) }
    else { legacy_checkout(cart) }
}

